def compute_module_total_buffer_size(
    model: nn.Module,
    dtype: Optional[Union[str, torch.device]] = None,
    special_dtypes: Optional[dict[str, Union[str, torch.device]]] = None,
):
    """
    Compute the total size of buffers in each submodule of a given model.
    """
    module_sizes = compute_module_sizes(model, dtype=dtype, special_dtypes=special_dtypes, buffers_only=True)
    return module_sizes.get("", 0)


def get_max_layer_size(
    modules: list[tuple[str, torch.nn.Module]], module_sizes: dict[str, int], no_split_module_classes: list[str]
):
    """
    Utility function that will scan a list of named modules and return the maximum size used by one full layer. The
    definition of a layer being:
    - a module with no direct children (just parameters and buffers)
    - a module whose class name is in the list `no_split_module_classes`

    Args:
        modules (`List[Tuple[str, torch.nn.Module]]`):
            The list of named modules where we want to determine the maximum layer size.
        module_sizes (`Dict[str, int]`):
            A dictionary mapping each layer name to its size (as generated by `compute_module_sizes`).
        no_split_module_classes (`List[str]`):
            A list of class names for layers we don't want to be split.

    Returns:
        `Tuple[int, List[str]]`: The maximum size of a layer with the list of layer names realizing that maximum size.
    """
    max_size = 0
    layer_names = []
    modules_to_treat = modules.copy()
    while len(modules_to_treat) > 0:
        module_name, module = modules_to_treat.pop(0)
        modules_children = list(module.named_children()) if isinstance(module, torch.nn.Module) else []
        if len(modules_children) == 0 or module.__class__.__name__ in no_split_module_classes:
            # No splitting this one so we compare to the max_size
            size = module_sizes[module_name]
            if size > max_size:
                max_size = size
                layer_names = [module_name]
            elif size == max_size:
                layer_names.append(module_name)
        else:
            modules_to_treat = [(f"{module_name}.{n}", v) for n, v in modules_children] + modules_to_treat
    return max_size, layer_names


def get_accelerator_free_memory(device_module, device_index: int) -> int:
    """Return free memory in bytes using the selected PyTorch accelerator API.

    Args:
        device_module:
            The API module returned by [`get_torch_accelerator_backend`].
        device_index (`int`):
            The index of the device to query.
    """
    if device_module is torch.accelerator:
        # get_memory_info was added in PyTorch 2.10.
        # Remove these fallbacks once our minimum PyTorch version is 2.10.
        if hasattr(device_module, "get_memory_info"):
            return device_module.get_memory_info(device_index)[0]
        device = torch.accelerator.current_accelerator()
        device_module = torch.get_device_module(device)
        if device.type == "tpu":
            # TorchTPU has no native mem_get_info or memory_allocated API.
            properties = device_module.get_device_properties(device_index)
            total_memory = getattr(properties, "hbm_bytes_per_device", None)
            if total_memory is None:
                total_memory = properties.total_memory
            allocated_memory = torch.accelerator.memory_allocated(device_index)
            return max(0, int(total_memory) - allocated_memory)
    return device_module.mem_get_info(device_index)[0]


def get_max_memory(max_memory: Optional[dict[Union[int, str], Union[int, str]]] = None):
    """
    Get the maximum memory available if nothing is passed, converts string to int otherwise.
    """
    import psutil

    device_type, device_module = get_torch_accelerator_backend()
    # MPS shares host memory and is addressed by its name rather than an integer index.
    num_devices = 0
    if device_type not in (None, "mps"):
        num_devices = device_module.device_count()
    devices = list(range(num_devices))
    if device_type == "tpu":
        # A TPU process can only use one chip
        devices = [torch.accelerator.current_device_index()]

    if max_memory is None:
        max_memory = {}
        is_integrated_cuda = False
        for i in devices:
            try:
                # Initialize each device before querying its available memory.
                _ = torch.tensor(0, device=f"{device_type}:{i}")
                max_memory[i] = get_accelerator_free_memory(device_module, i)
                if device_type == "cuda":
                    properties = device_module.get_device_properties(i)
                    is_integrated_cuda = is_integrated_cuda or getattr(properties, "is_integrated", False)
            except Exception as error:
                logger.info(f"Could not determine memory for {device_type}:{i}: {error}")
        # MPS and integrated CUDA devices share host RAM, so exposing a separate CPU budget would double-count it.
        if device_type == "mps":
            max_memory["mps"] = psutil.virtual_memory().available
        elif not is_integrated_cuda:
            max_memory["cpu"] = psutil.virtual_memory().available
        return max_memory

    for key in max_memory:
        if isinstance(max_memory[key], str):
            max_memory[key] = convert_file_size_to_int(max_memory[key])

    # Allocate accelerator devices first, in index order.
    gpu_devices = sorted(k for k in max_memory if isinstance(k, int))
    for device in gpu_devices:
        if device not in devices:
            logger.warning(f"Device {device} is not available, available devices are {devices}")
    # Add the other devices in the preset order if they are available
    all_devices = gpu_devices + [k for k in ["mps", "cpu", "disk"] if k in max_memory.keys()]
    # Raise an error if a device is not recognized
    for k in max_memory.keys():
        if k not in all_devices:
            raise ValueError(
                f"Device {k} is not recognized, available devices are integers(for GPU/XPU), 'mps', 'cpu' and 'disk'"
            )
    max_memory = {k: max_memory[k] for k in all_devices}

    return max_memory

